#!/usr/bin/env python3
"""Combine the reports generated by the current reproduction run."""
import json
from pathlib import Path

P = Path(__file__).resolve().parents[2]
reports = {
    "transcendental": "numerical/external26/verification_round29.json",
    "analytic_grid": "numerical/fullgrid27/verification_round29.json",
    "arithmetic": "numerical/global28/verification.json",
}
result = {key: json.loads((P / path).read_text()) for key, path in reports.items()}
assert result["transcendental"]["status"] == "PASS"
assert result["transcendental"]["complete"]
assert result["analytic_grid"]["status"] == "PASS"
assert result["analytic_grid"]["complete"]
assert result["arithmetic"]["passed"]
(P / "numerical/final29/numerical_rechecks.json").write_text(
    json.dumps(result, indent=2) + "\n"
)
